import{_ as p,r as s,o as l,c as o,e as n,a as c,s as i}from"./chunks/framework.CXcwiNg-.js";const f=JSON.parse('{"title":"{% flash %} - October CMS - 3.x","titleTemplate":false,"description":"Twig-тег","frontmatter":{"subtitle":"Twig-тег"},"headers":[{"level":2,"title":"Сохранение flash-сообщений в Twig-переменную","slug":"сохранение-flash-сообщении-в-twig-переменную","link":"#сохранение-flash-сообщении-в-twig-переменную","children":[{"level":4,"title":"См. также","slug":"см-также","link":"#см-также","children":[]}]}],"relativePath":"3.x/ru/markup/tag/flash.md","filePath":"3.x/ru/markup/tag/flash.md"}'),u={name:"3.x/ru/markup/tag/flash.md"};function g(r,a,k,d,m,h){const t=s("pre-heading"),e=s("post-heading");return l(),o("div",null,[n(t),a[0]||(a[0]=c("h1",null,"{% flash %}",-1)),n(e),a[1]||(a[1]=i(`<div class="custom-block aside"><p>Обратитесь к <a href="./../../cms/features/flash-messages.html">статье о Flash-сообщениях</a>, чтобы узнать больше об использовании flash-сообщений.</p></div><p>Теги <code>{% flash %}</code> и <code>{% endflash %}</code> рендерят все flash-сообщения, сохранённые в сессии пользователя и установленные PHP-классом <code>Flash</code>. Переменная <code>message</code> внутри будет содержать текст flash-сообщения, а разметка внутри будет повторяться для нескольких flash-сообщений.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>ul</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
        <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>li</span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>li</span><span class="token punctuation">&gt;</span></span>
    <span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
<span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>ul</span><span class="token punctuation">&gt;</span></span>
</code></pre></div><p>Вы можете использовать переменную <code>type</code>, которая представляет тип flash-сообщения — <strong>success</strong>, <strong>error</strong>, <strong>info</strong> или <strong>warning</strong>.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-<span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> type <span class="token delimiter punctuation">}}</span></span><span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span>
        <span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Вы также можете указать <code>type</code> для фильтрации flash-сообщений определённого типа. Следующий пример покажет только сообщения <strong>success</strong> — если есть сообщение <strong>error</strong>, оно не будет отображено.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">flash</span> success <span class="token delimiter punctuation">%}</span></span>
    <span class="token tag"><span class="token tag"><span class="token punctuation">&lt;</span>div</span> <span class="token attr-name">class</span><span class="token attr-value"><span class="token punctuation attr-equals">=</span><span class="token punctuation">&quot;</span>alert alert-success<span class="token punctuation">&quot;</span></span><span class="token punctuation">&gt;</span></span><span class="token twig language-twig"><span class="token delimiter punctuation">{{</span> message <span class="token delimiter punctuation">}}</span></span><span class="token tag"><span class="token tag"><span class="token punctuation">&lt;/</span>div</span><span class="token punctuation">&gt;</span></span>
<span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">endflash</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h2 id="сохранение-flash-сообщении-в-twig-переменную"><a href="#сохранение-flash-сообщении-в-twig-переменную" class="header-anchor">#</a> Сохранение flash-сообщений в Twig-переменную</h2><p>В любом шаблоне вы можете сохранить flash-сообщения в переменную с помощью функции <code>flash()</code>. Это позволяет манипулировать выводом перед отображением. Функция возвращает массив с одним flash-сообщением на каждый тип.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> messages <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Первый аргумент может указывать тип сообщения — в этом случае возвращается сообщение как строка.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> successMessage <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>success<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><p>Если первый аргумент установлен в <strong>all</strong>, функция вернёт массив типов, каждый из которых является массивом всех flash-сообщений.</p><div class="language-twig extra-class"><pre class="language-twig"><code><span class="token twig language-twig"><span class="token delimiter punctuation">{%</span> <span class="token tag-name keyword">set</span> allMessages <span class="token operator">=</span> flash<span class="token punctuation">(</span><span class="token string"><span class="token punctuation">&#39;</span>all<span class="token punctuation">&#39;</span></span><span class="token punctuation">)</span> <span class="token delimiter punctuation">%}</span></span>
</code></pre></div><h4 id="см-также"><a href="#см-также" class="header-anchor">#</a> См. также</h4><div class="custom-block also"><ul><li><a href="./../../cms/features/flash-messages.html">Flash-сообщения</a></li></ul></div>`,16))])}const v=p(u,[["render",g]]);export{f as __pageData,v as default};
